    Differential Revision: https://phabricator.services.mozilla.com/D265861

diff --git a/mail/locales/en-US/messenger/activityFeedback.ftl b/mail/locales/en-US/messenger/activityFeedback.ftl
index 90b53cf2dfc..5df5696d14d 100644
--- a/mail/locales/en-US/messenger/activityFeedback.ftl
+++ b/mail/locales/en-US/messenger/activityFeedback.ftl
@@ -19,4 +19,8 @@ looking-for-messages-folder = Looking for new messages in { $folderName }…
 # Variables:
 # $number (Number) - Number of messages being deleted.
 # $folderName (String) - The folder's name.
-deleting-messages = Deleting { $number } message(s) from { $folderName }…
+deleting-message =
+  { $number ->
+      [one] Deleting one message from { $folderName }…
+     *[other] Deleting { $number } messages from { $folderName }…
+  }
diff --git a/mailnews/protocols/ews/src/EwsFolder.cpp b/mailnews/protocols/ews/src/EwsFolder.cpp
index 2e04c5bdbfe..54eef65aad9 100644
--- a/mailnews/protocols/ews/src/EwsFolder.cpp
+++ b/mailnews/protocols/ews/src/EwsFolder.cpp
@@ -828,7 +828,7 @@ NS_IMETHODIMP EwsFolder::DeleteMessages(

       ErrorResult error;
       nsCString message;
-      l10n->FormatValueSync("deleting-messages"_ns, l10nArgs, message, error);
+      l10n->FormatValueSync("deleting-message"_ns, l10nArgs, message, error);

       // Show the formatted message in the status bar.
       rv = aMsgWindow->GetStatusFeedback(getter_AddRefs(feedback));
diff --git a/mailnews/protocols/ews/test/browser/browser_feedback.js b/mailnews/protocols/ews/test/browser/browser_feedback.js
index d813a205f66..1226f838aa1 100644
--- a/mailnews/protocols/ews/test/browser/browser_feedback.js
+++ b/mailnews/protocols/ews/test/browser/browser_feedback.js
@@ -221,7 +221,7 @@ add_task(async function test_delete_message() {

   // Build the string we expect to see in the status bar.
   const l10n = new Localization(["messenger/activityFeedback.ftl"], true);
-  const expectedStatus = l10n.formatValueSync("deleting-messages", {
+  const expectedStatus = l10n.formatValueSync("deleting-message", {
     number: "1",
     folderName,
   });
